    for a in (1, 2):
        F[f'Mouse_{a}_poly_area'] = np.array([_hull_area(p) for p in arr[a]]) / PX_PER_MM ** 2
    for a in (1, 2):
        F[f'Mouse_{a}_nose_to_tail'] = _d(P, 'Nose', a, 'Tail_base', a)
    for a in (1, 2): F[f'Mouse_{a}_width'] = _d(P, 'Lat_left', a, 'Lat_right', a)
